import os,re,json,glob,html
from reportlab.lib.pagesizes import A4
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,ListFlowable,ListItem
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.units import mm
ROOT='/mnt/data/qa_final2'
D=json.load(open(ROOT+'/content/topics.json',encoding='utf8'))
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='B',parent=styles['BodyText'],fontSize=9.7,leading=14.2,textColor=colors.HexColor('#294b68'),spaceAfter=4))
styles.add(ParagraphStyle(name='S',parent=styles['BodyText'],fontSize=8.2,leading=11.2,textColor=colors.HexColor('#617b91')))
styles.add(ParagraphStyle(name='C',parent=styles['BodyText'],fontName='Courier',fontSize=8.1,leading=11.4,backColor=colors.HexColor('#f2f8fc'),borderColor=colors.HexColor('#c8deed'),borderWidth=.5,borderPadding=6,spaceBefore=3,spaceAfter=5))
styles.add(ParagraphStyle(name='H2x',parent=styles['Heading2'],fontSize=14.2,leading=18,textColor=colors.HexColor('#123f6d'),spaceBefore=9,spaceAfter=5))

def esc(s): return html.escape(str(s))
def hf(c,doc):
 c.saveState();w,h=A4
 c.setFillColor(colors.HexColor('#1769aa'));c.roundRect(18*mm,h-16*mm,10*mm,10*mm,2.5*mm,fill=1,stroke=0)
 c.setFillColor(colors.white);c.setFont('Helvetica-Bold',8.5);c.drawCentredString(23*mm,h-12.5*mm,'QA')
 c.setFillColor(colors.HexColor('#123f6d'));c.setFont('Helvetica-Bold',9.5);c.drawString(31*mm,h-10.7*mm,'QA LAB BRASIL')
 c.setFillColor(colors.HexColor('#668096'));c.setFont('Helvetica',7);c.drawString(31*mm,h-14.1*mm,'Quality Engineering')
 c.setStrokeColor(colors.HexColor('#d4e5f1'));c.line(18*mm,h-18*mm,w-18*mm,h-18*mm)
 c.setFillColor(colors.HexColor('#7890a3'));c.setFont('Helvetica',7);c.drawRightString(w-18*mm,9*mm,f'QA Lab Brasil  |  {doc.page}')
 c.restoreState()

def build(path,title,subtitle,sections):
 story=[Spacer(1,5*mm),Paragraph(esc(title),styles['Title']),Paragraph(esc(subtitle),styles['B']),Spacer(1,4)]
 for h,body in sections:
  story.append(Paragraph(esc(h),styles['H2x']))
  for line in body if isinstance(body,list) else str(body).split('\n'):
   line=str(line).strip()
   if not line: continue
   if line.startswith('$ '): story.append(Paragraph(esc(line[2:]),styles['C'])); continue
   if re.match(r'^(python|py|pip|npm|npx|node|java|javac|robot|appium|adb|git|docker|kubectl|terraform|k6|mvn|gradle|jenkins|jmeter|locust|code|allure|cypress|pact|wiremock|prometheus|grafana|sonar|zap|curl|echo|mkdir|cd |source |\.\\|\.venv)',line,re.I): story.append(Paragraph(esc(line),styles['C'])); continue
   if re.match(r'^\d+[\.)]\s',line): story.append(Paragraph('<b>'+esc(line)+'</b>',styles['B']))
   elif ':' in line and len(line.split(':',1)[0])<45:
    a,b=line.split(':',1); story.append(Paragraph('<b>'+esc(a)+':</b> '+esc(b),styles['B']))
   else: story.append(Paragraph(esc(line),styles['B']))
  story.append(Spacer(1,3))
 doc=SimpleDocTemplate(path,pagesize=A4,rightMargin=18*mm,leftMargin=18*mm,topMargin=22*mm,bottomMargin=16*mm,title=title)
 doc.build(story,onFirstPage=hf,onLaterPages=hf)

