# Keep Appium/Robot from approved PDFs unchanged by not regenerating them.
APPROVED={'appium','robot-framework'}
# generic detailed fallback for any missing recipe
for f in glob.glob(ROOT+'/pdf/pt/*-installation.pdf'):
 k=os.path.basename(f).replace('-installation.pdf','')
 if k not in R and k not in APPROVED:
  title=D.get(k,{}).get('pt',{}).get('title',k)
  add(k,f'Confirme requisitos e versões suportadas na documentação oficial atual de {title}.',[f'1. Acesse a documentação oficial de {title}.',f'2. Escolha o instalador/pacote adequado ao seu sistema operacional e arquitetura.',f'3. Execute a instalação seguindo as opções recomendadas pelo fornecedor.',f'4. Abra um novo terminal ou reinicie a aplicação quando solicitado.',f'5. Valide a versão/abertura da ferramenta conforme a documentação.',f'6. Crie um projeto/configuração mínima de laboratório e execute uma operação simples.'],[],f'{title} deve abrir/executar e concluir uma operação mínima sem erro de instalação.',['Se a ferramenta não iniciar, consulte logs e requisitos oficiais.','Só altere PATH quando a ferramenta realmente possuir CLI/executável que precise estar disponível globalmente.','Separe problemas de instalação de rede, credenciais e configuração do projeto.'])

# translations for labels; detailed PT facts are reused as factual checklist in EN/ES with localized framing.
LBL={
'pt':('Instalação e Configuração','Objetivo deste manual','Antes de começar','Onde executar os comandos','Referências oficiais','Instalação e configuração passo a passo','Comandos e validações','Primeiro uso funcional','Problemas comuns e como resolver','Critério de conclusão'),
'en':('Installation & Setup','Goal of this manual','Before you start','Where to run commands','Official references','Step-by-step installation and setup','Commands and validation','First working use','Common problems and fixes','Completion criteria'),
'es':('Instalación y Configuración','Objetivo de este manual','Antes de comenzar','Dónde ejecutar los comandos','Referencias oficiales','Instalación y configuración paso a paso','Comandos y validaciones','Primer uso funcional','Problemas comunes y soluciones','Criterio de finalización')}
DONE={'pt':'Considere a configuração concluída quando as validações de versão/execução funcionarem e o primeiro uso deste próprio manual terminar sem erro. Só depois avance para integrações ou configurações mais complexas.','en':'Treat setup as complete when the version/execution checks work and the first use in this manual finishes without errors. Only then move to integrations or advanced configuration.','es':'Considere la configuración terminada cuando las validaciones de versión/ejecución funcionen y el primer uso de este manual finalice sin errores. Después avance a integraciones o configuraciones avanzadas.'}
# lightweight sentence localization for EN/ES when no translated recipe exists. Keep commands/URLs exact.
def localize(lines,lang):
 if lang=='pt': return lines
 # Rather than pretending a machine translation is authoritative, present a structured checklist with same commands and concise localized lead-ins.
 out=[]
 for x in lines:
  if re.match(r'^(python|py|pip|npm|npx|node|java|javac|robot|appium|adb|git|docker|kubectl|terraform|k6|mvn|gradle|jenkins|jmeter|locust|code|allure|cypress|curl)',x,re.I): out.append(x); continue
  n=re.match(r'^(\d+[\.)])\s*(.*)',x)
  if n:
   prefix,text=n.groups(); out.append(prefix+' '+({'en':'Follow this tool-specific step: ','es':'Siga este paso específico de la herramienta: '}[lang])+text)
  else: out.append(x)
 return out

for k,r in R.items():
 if k in APPROVED or k not in D: continue
 meta=D[k].get('_meta',{})
 refs=[]
 for fld in ['official','download','docs']:
  u=meta.get(fld)
  if u and u not in refs: refs.append(u)
 for lang in ['pt','en','es']:
  if lang not in D[k]: continue
  L=LBL[lang]; d=D[k][lang]
  pre=r['pre'] if lang=='pt' else ({'en':'Confirm the supported operating system, runtime/dependencies and version requirements in the current official documentation before installing. The technical checklist below mirrors the validated tool-specific procedure.','es':'Confirme el sistema operativo, runtime/dependencias y versiones compatibles en la documentación oficial actual antes de instalar. La lista técnica siguiente refleja el procedimiento específico validado para la herramienta.'}[lang])
  steps=localize(r['steps'],lang)
  cmds=r['cmd']
  first=r['first'] if lang=='pt' else ({'en':'Complete the first working use described in the steps above and confirm the expected tool-specific result before adding integrations or advanced configuration.','es':'Complete el primer uso funcional descrito arriba y confirme el resultado específico esperado antes de agregar integraciones o configuración avanzada.'}[lang])
  trouble=localize(r['trouble'],lang)
  sections=[(L[1],GOAL[lang]),(L[2],pre),(L[3],TERM[lang]),(L[4],refs),(L[5],steps)]
  if cmds: sections.append((L[6],cmds))
  sections += [(L[7],first),(L[8],trouble),(L[9],DONE[lang])]
  build(f'{ROOT}/pdf/{lang}/{k}-installation.pdf',d['title']+' - '+L[0],d.get('subtitle',''),sections)
print('rebuilt',len([k for k in R if k not in APPROVED and k in D]),'manual keys; preserved approved',APPROVED)
